using System;
using System.Drawing;
using System.IO;
using System.Text;
using System.Windows.Forms;
class LauncherTests {
 static int checks;
 static void Assert(bool value,string message){if(!value)throw new Exception(message);checks++;}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Assert(rejected,message);}
 static UpdateFile Entry(string path,string staged){return new UpdateFile{path=path,url="https://example.invalid/"+Uri.EscapeDataString(path),size=new FileInfo(staged).Length,sha256=Launcher.Hash(staged)};}
 [STAThread] static int Main(string[] args){
  string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Launcher.Root=root;File.WriteAllText(Path.Combine(root,".kreyli-install"),"test");Directory.CreateDirectory(Path.Combine(root,"saves"));File.WriteAllText(Path.Combine(root,"saves","keep.txt"),"save");File.WriteAllText(Path.Combine(root,"launcher-profile.json"),"{\"nickname\":\"Kreyli QA\"}");
  foreach(string bad in new[]{"../shared-agent.jar","saves/keep.txt","settings/config.txt","game.jar","C:/evil.exe","shared-agent.jar:evil","shared-agent.jar.","UI/foo.png","launcher-profile.json","update-channel.json"})Reject(()=>Launcher.SafePath(root,bad),"path accepted "+bad);
  Assert(Launcher.Nick("  Николай  ")=="Николай","nickname trim");Reject(()=>Launcher.Nick("x;break"),"semicolon accepted");Reject(()=>Launcher.Nick("a\nb"),"control accepted");
  string stage=Path.Combine(root,".updates","good");Directory.CreateDirectory(stage);File.WriteAllText(Path.Combine(root,"shared-agent.jar"),"old");File.WriteAllText(Path.Combine(stage,"shared-agent.jar"),"new");
  var m=new UpdateManifest{version="1.2.0",files=new[]{Entry("shared-agent.jar",Path.Combine(stage,"shared-agent.jar"))}};File.WriteAllText(Path.Combine(stage,"manifest.json"),Launcher.Json.Serialize(m));Launcher.Apply(root,stage);Assert(File.ReadAllText(Path.Combine(root,"shared-agent.jar"))=="new","update failed");Assert(File.ReadAllText(Path.Combine(root,"saves","keep.txt"))=="save","save changed");Assert(File.ReadAllText(Path.Combine(root,"launcher-profile.json")).Contains("Kreyli QA"),"profile changed");
  File.WriteAllText(Path.Combine(stage,"shared-agent.jar"),"corrupt");Reject(()=>Launcher.Apply(root,stage),"corruption accepted");Assert(File.ReadAllText(Path.Combine(root,"shared-agent.jar"))=="new","corruption changed installation");
  string fail=Path.Combine(root,".updates","failure");Directory.CreateDirectory(fail);File.WriteAllText(Path.Combine(fail,"shared-agent.jar"),"newer");File.WriteAllText(Path.Combine(fail,"shared-support.jar"),"support");Directory.CreateDirectory(Path.Combine(root,"shared-support.jar"));
  m.files=new[]{Entry("shared-agent.jar",Path.Combine(fail,"shared-agent.jar")),Entry("shared-support.jar",Path.Combine(fail,"shared-support.jar"))};File.WriteAllText(Path.Combine(fail,"manifest.json"),Launcher.Json.Serialize(m));Reject(()=>Launcher.Apply(root,fail),"failure not raised");Assert(File.ReadAllText(Path.Combine(root,"shared-agent.jar"))=="new","rollback failed");Assert(File.ReadAllText(Path.Combine(root,"installed-version.txt"))=="1.2.0","version changed on failure");
  m.files[0].url="http://example.invalid/no";Reject(()=>Launcher.Validate(m,root),"HTTP accepted");m.files[0].url="https://example.invalid/ok";m.files[1]=m.files[0];Reject(()=>Launcher.Validate(m,root),"duplicate accepted");Assert(!Launcher.Configured(),"missing endpoint considered configured");Assert(Launcher.CheckUpdate()==null,"offline no endpoint failed");
  string libraryStage=Path.Combine(root,".updates","library");Directory.CreateDirectory(Path.Combine(libraryStage,"lib"));File.WriteAllText(Path.Combine(libraryStage,"lib","steamworks4j-1.9.0.jar"),"official fixture");
  var libManifest=new UpdateManifest{version="1.3.0",files=new[]{Entry("lib/steamworks4j-1.9.0.jar",Path.Combine(libraryStage,"lib","steamworks4j-1.9.0.jar"))}};File.WriteAllText(Path.Combine(libraryStage,"manifest.json"),Launcher.Json.Serialize(libManifest));Launcher.Apply(root,libraryStage);Assert(File.ReadAllText(Path.Combine(root,"lib","steamworks4j-1.9.0.jar"))=="official fixture","nested library update");
  File.WriteAllText(Path.Combine(root,"manual-updates.flag"),"manual");Application.EnableVisualStyles();using(var form=new LauncherWindow(new string[0])){foreach(Control control in form.Controls)Assert(!(control is CheckBox),"automatic update switch still exposed");form.Show();for(int i=0;i<20;i++){Application.DoEvents();System.Threading.Thread.Sleep(10);}using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(Path.Combine(root,"launcher-preview.png"));}var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(LauncherWindow).GetField("pending",flags).SetValue(form,new UpdateManifest{version="9.0.0"});typeof(LauncherWindow).GetMethod("RefreshState",flags).Invoke(form,null);Assert(((Button)typeof(LauncherWindow).GetField("play",flags).GetValue(form)).Text=="Обновить","update must precede install");var op=(System.Threading.Tasks.Task)typeof(LauncherWindow).GetMethod("FileOperation",flags).Invoke(form,new object[]{new Action(()=>{}),false});var until=DateTime.UtcNow.AddSeconds(5);while(!op.IsCompleted&&DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}Assert(op.IsCompleted,"file operation timed out");op.GetAwaiter().GetResult();Assert(((System.Windows.Forms.Timer)typeof(LauncherWindow).GetField("autoTimer",flags).GetValue(form)).Enabled,"automatic update must resume after file operation");}
  Console.WriteLine("KREYLI_LAUNCHER_TESTS: PASS checks="+checks);return 0;
 }
}

